CREATE TABLE IF NOT EXISTS "perfil" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"nome" VARCHAR(50) NOT NULL UNIQUE,
	"descricao" VARCHAR(255),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "usuario" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"perfil_id" INTEGER NOT NULL,
	"nome" VARCHAR(120) NOT NULL,
	"email" VARCHAR(150) NOT NULL UNIQUE,
	"senha_hash" VARCHAR(255) NOT NULL,
	"ativo" BOOLEAN NOT NULL DEFAULT true,
	"ultimo_acesso" TIMESTAMP,
	"criado_em" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "recuperacao_senha" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"usuario_id" INTEGER NOT NULL,
	"token_hash" VARCHAR(255) NOT NULL,
	"expira_em" TIMESTAMP NOT NULL,
	"usado_em" TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "log_auditoria" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"usuario_id" INTEGER,
	"acao" VARCHAR(50) NOT NULL,
	"entidade" VARCHAR(60),
	"entidade_id" INTEGER,
	"detalhes" TEXT,
	"data_hora" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "unidade" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"nome" VARCHAR(120) NOT NULL UNIQUE,
	"endereco" VARCHAR(255),
	"ativa" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "espaco" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"unidade_id" INTEGER NOT NULL,
	"nome" VARCHAR(100) NOT NULL,
	"tipo" VARCHAR(50) NOT NULL,
	"capacidade" INTEGER,
	"descricao" VARCHAR(255),
	"situacao" VARCHAR(30) NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "patrimonio" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"unidade_id" INTEGER NOT NULL,
	"espaco_id" INTEGER,
	"codigo" VARCHAR(30) NOT NULL UNIQUE,
	"nome" VARCHAR(120) NOT NULL,
	"categoria" VARCHAR(60),
	"estado_conservacao" VARCHAR(30) NOT NULL,
	"situacao" VARCHAR(30) NOT NULL,
	"data_aquisicao" DATE,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "movimentacao_patrimonio" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"patrimonio_id" INTEGER NOT NULL,
	"espaco_destino_id" INTEGER,
	"usuario_id" INTEGER NOT NULL,
	"tipo" VARCHAR(30) NOT NULL,
	"data" DATE NOT NULL,
	"motivo" VARCHAR(255),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "projeto" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"unidade_id" INTEGER NOT NULL,
	"responsavel_id" INTEGER NOT NULL,
	"codigo" VARCHAR(30) NOT NULL UNIQUE,
	"nome" VARCHAR(150) NOT NULL,
	"descricao" TEXT,
	"objetivos" TEXT,
	"data_inicio" DATE NOT NULL,
	"data_fim" DATE,
	"status" VARCHAR(30) NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "categoria" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"nome" VARCHAR(60) NOT NULL UNIQUE,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "projeto_categoria" (
	"projeto_id" INTEGER NOT NULL,
	"categoria_id" INTEGER NOT NULL,
	PRIMARY KEY("projeto_id", "categoria_id")
);

CREATE TABLE IF NOT EXISTS "atividade" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"projeto_id" INTEGER NOT NULL,
	"nome" VARCHAR(150) NOT NULL,
	"data" DATE,
	"concluida" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "historico_projeto" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"projeto_id" INTEGER NOT NULL,
	"usuario_id" INTEGER NOT NULL,
	"descricao" VARCHAR(255) NOT NULL,
	"data_hora" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "utilizacao_espaco" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"espaco_id" INTEGER NOT NULL,
	"projeto_id" INTEGER,
	"responsavel_id" INTEGER NOT NULL,
	"data" DATE NOT NULL,
	"hora_inicio" TIME NOT NULL,
	"hora_fim" TIME,
	"atividade" VARCHAR(150),
	"qtd_participantes" INTEGER,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "beneficiario" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"nome" VARCHAR(120) NOT NULL,
	"data_nascimento" DATE,
	"cpf" CHAR(11) UNIQUE,
	"contato" VARCHAR(100),
	"ativo" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "atendimento" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"beneficiario_id" INTEGER NOT NULL,
	"projeto_id" INTEGER,
	"unidade_id" INTEGER NOT NULL,
	"responsavel_id" INTEGER NOT NULL,
	"data" DATE NOT NULL,
	"tipo" VARCHAR(60) NOT NULL,
	"situacao" VARCHAR(30) NOT NULL,
	"observacoes" TEXT,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "frequencia" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"atividade_id" INTEGER NOT NULL,
	"beneficiario_id" INTEGER NOT NULL,
	"registrado_por" INTEGER NOT NULL,
	"status" VARCHAR(30) NOT NULL,
	"justificativa" VARCHAR(255),
	"registrado_em" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id"),
	CONSTRAINT "frequencia_unique_0" UNIQUE ("atividade_id", "beneficiario_id")
);

CREATE TABLE IF NOT EXISTS "voluntario" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"nome" VARCHAR(120) NOT NULL,
	"cpf" CHAR(11) UNIQUE,
	"telefone" VARCHAR(20),
	"email" VARCHAR(150),
	"area_atuacao" VARCHAR(80),
	"disponibilidade" VARCHAR(120),
	"situacao" VARCHAR(30) NOT NULL,
	"data_cadastro" DATE NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "participacao_voluntario" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"voluntario_id" INTEGER NOT NULL,
	"atividade_id" INTEGER NOT NULL,
	"data" DATE NOT NULL,
	"horas" DECIMAL(5,2),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "visita" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"unidade_id" INTEGER NOT NULL,
	"responsavel_id" INTEGER NOT NULL,
	"data" DATE NOT NULL,
	"visitado" VARCHAR(150) NOT NULL,
	"finalidade" VARCHAR(255) NOT NULL,
	"observacoes" TEXT,
	"resultado" TEXT,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "refeicao" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"unidade_id" INTEGER NOT NULL,
	"responsavel_id" INTEGER NOT NULL,
	"data" DATE NOT NULL,
	"tipo_refeicao" VARCHAR(30) NOT NULL,
	"quantidade_servida" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "indicador" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"nome" VARCHAR(100) NOT NULL UNIQUE,
	"descricao" VARCHAR(255),
	"unidade_medida" VARCHAR(30),
	"modulo" VARCHAR(40),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "resultado_indicador" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"indicador_id" INTEGER NOT NULL,
	"unidade_id" INTEGER NOT NULL,
	"periodo_inicio" DATE NOT NULL,
	"periodo_fim" DATE NOT NULL,
	"valor" DECIMAL(14,2) NOT NULL,
	"atualizado_em" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id"),
	CONSTRAINT "resultado_indicador_unique_0" UNIQUE ("indicador_id", "unidade_id", "periodo_inicio", "periodo_fim")
);

CREATE TABLE IF NOT EXISTS "relatorio" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"usuario_id" INTEGER NOT NULL,
	"nome" VARCHAR(150) NOT NULL,
	"tipo" VARCHAR(60) NOT NULL,
	"periodo_inicio" DATE,
	"periodo_fim" DATE,
	"formato" VARCHAR(30) NOT NULL,
	"filtros" TEXT,
	"colunas" TEXT,
	"status" VARCHAR(30) NOT NULL,
	"gerado_em" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "importacao_csv" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"usuario_id" INTEGER NOT NULL,
	"tabela_destino" VARCHAR(60) NOT NULL,
	"nome_arquivo" VARCHAR(200) NOT NULL,
	"linhas_importadas" INTEGER NOT NULL DEFAULT 0,
	"status" VARCHAR(30) NOT NULL,
	"data_hora" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY("id")
);

